<script lang="ts">import { BarChart, type BarChartBar } from '@microcks/deep-ink'; const HOURS=[12,8,4,3,2,5,18,40,85,72,64,66]; let id=$state('11'); const bars: BarChartBar[] = Array.from({length:24},(_,h)=>{const v=HOURS[h];const hh=String(h).padStart(2,'0');return v === undefined ? {id:String(h),value:0,future:true,description:`${hh}:00, not yet`,label:h%3===0?`${hh}h`:''} : {id:String(h),value:v,description:`${hh}:00 to ${String(h+1).padStart(2,'0')}:00, ${v} invocations`,label:h%3===0?`${hh}h`:''};});</script><div style="max-width:900px"><BarChart label="Invocations per hour for API Pastry 2.0. Peak 85." {bars} max={90} selection="fill" height={200} gap={6} grid={[0,0.5]} selectedId={id} onselect={v=>id=v} ticks={['90','45','0']} table={{caption:'Invocations per hour, today',columns:['Hour','Invocations'],rows:HOURS.map((v,h)=>[`${String(h).padStart(2,'0')}:00`,String(v)])}}/></div>
